import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {TextAreaComponent} from "./textArea.component";
import {PI_TEXT_AREA_ACTION, PI_TEXT_AREA_CARD} from "./textArea.types";

export * from "./textArea.types";

registerCardComponent({
  name: PI_TEXT_AREA_CARD,
  component: TextAreaComponent,
  events: actionTypesToEvents(PI_TEXT_AREA_ACTION),
});

import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Textarea} from "@/components/ui/textarea";
import {useFormContext} from "@/cards/form/form.context";
import {cn} from "@/lib/utils";
import type {
  CssLength,
  PiTextAreaEvents,
  PiTextAreaProps,
} from "./textArea.types";

function toCssLength(v: CssLength | undefined): string | undefined {
  if (v === undefined) return undefined;
  return typeof v === "number" ? `${v}px` : v;
}

export const TextAreaComponent = (
  props: PiCardProps<PiTextAreaProps, PiTextAreaEvents>,
): React.ReactNode => {
  const {
    name,
    value: propValue = "",
    placeholder,
    disabled,
    readOnly,
    rows = 4,
    cols,
    fieldSizing = "fixed",
    resize,
    minHeight,
    maxHeight,
    width,
    height,
    maxWidth,
    dir,
    writingMode,
    submitOnEnter,
    className,
    style,
    cardName,
    onChanged,
    onSubmitted,
  } = props;

  // `id` may be injected by a parent pi/field card via Pihanga's extra-prop
  // forwarding. Not part of the official type so read through an escape hatch.
  const injectedId = (props as {id?: string}).id;
  const invalid = Boolean((props as {invalid?: boolean}).invalid);

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  const value = useFormData
    ? ((form.formData[name!] as string | undefined) ?? "")
    : propValue;

  function commitChange(newValue: string) {
    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      onChanged({name, value: newValue});
    }
  }

  function handleChange(e: React.ChangeEvent<HTMLTextAreaElement>) {
    commitChange(e.target.value);
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (
      submitOnEnter &&
      e.key === "Enter" &&
      !e.shiftKey &&
      !e.ctrlKey &&
      !e.metaKey &&
      !e.altKey
    ) {
      e.preventDefault();
      onSubmitted({name, value: e.currentTarget.value});
    }
  }

  // Default resize behaviour: content-sizing boxes shouldn't be manually
  // resizable (dragging writes an inline width/height that permanently
  // defeats field-sizing: content).
  const resolvedResize =
    resize ?? (fieldSizing === "content" ? "none" : "vertical");

  const resizeClass =
    resolvedResize === "none"
      ? "resize-none"
      : resolvedResize === "vertical"
        ? "resize-y"
        : resolvedResize === "horizontal"
          ? "resize-x"
          : "resize";

  // `field-sizing` is expressed as a Tailwind utility class (shipped by
  // Tailwind v4) rather than an inline style — this is both more idiomatic
  // for this codebase (the base Textarea already defaults to
  // `field-sizing-content`) and avoids relying on very new CSS properties
  // being present in every CSSStyleDeclaration IDL implementation.
  const fieldSizingClass =
    fieldSizing === "content" ? "field-sizing-content" : "field-sizing-fixed";

  const inlineStyle: React.CSSProperties = {
    minHeight: toCssLength(minHeight),
    maxHeight: toCssLength(maxHeight),
    width: toCssLength(width),
    height: toCssLength(height),
    maxWidth: toCssLength(maxWidth),
    writingMode,
    ...style,
  };

  // Use the id injected by pi/field (for label↔control linking); fall back
  // to a locally-generated id when used standalone.
  const selfId = `${cardName}-${name ?? "field"}`;
  const fieldId = injectedId ?? selfId;

  return (
    <Textarea
      id={fieldId}
      value={value}
      onChange={handleChange}
      onKeyDown={handleKeyDown}
      placeholder={placeholder}
      disabled={disabled}
      readOnly={readOnly}
      rows={fieldSizing === "fixed" ? rows : undefined}
      cols={fieldSizing === "fixed" ? cols : undefined}
      dir={dir}
      aria-invalid={invalid || undefined}
      data-pihanga={cardName}
      className={cn(fieldSizingClass, resizeClass, className)}
      style={inlineStyle}
    />
  );
};

import type {CSSProperties} from "react";
import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_TEXT_AREA_CARD = "pi/text-area";

export const TextArea = createCardDeclaration<
  PiTextAreaProps,
  PiTextAreaEvents
>(PI_TEXT_AREA_CARD);

export const PI_TEXT_AREA_ACTION = registerActions(PI_TEXT_AREA_CARD, [
  "changed",
  "submitted",
]);

export const onTextAreaChanged = createOnAction<PiTextAreaChangedEvent>(
  PI_TEXT_AREA_ACTION.CHANGED,
);

export const onTextAreaSubmitted = createOnAction<PiTextAreaSubmittedEvent>(
  PI_TEXT_AREA_ACTION.SUBMITTED,
);

/** A CSS length. Numbers are treated as pixels, strings are used verbatim. */
export type CssLength = number | string;

/**
 * How the textarea sizes itself:
 *  - "fixed"   (default) — plain `<textarea>` behaviour. Size is governed by
 *              `rows`/`cols` (and any explicit `width`/`height`); the user
 *              may resize it per the `resize` prop. Never grows with content.
 *  - "content" — uses the CSS `field-sizing: content` behaviour: the box
 *              grows/shrinks to fit its content, clamped by any
 *              `minHeight`/`maxHeight`/`width`/`height`/`maxWidth` you set.
 *              `rows`/`cols` are ignored by the browser once this is active.
 */
export type PiTextAreaFieldSizing = "fixed" | "content";

export type PiTextAreaResize = "none" | "vertical" | "horizontal" | "both";

export type PiTextAreaProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its value from form state and writes
   * back via form.handleChange.
   */
  name?: string;

  /**
   * Controlled value used in standalone mode (outside a Form).
   * Ignored when `name` is set and the component is inside a pi/form.
   */
  value?: string;

  /** Placeholder text shown when the box is empty. May contain `\n`. */
  placeholder?: string;

  /** When true, the textarea is disabled and non-interactive. */
  disabled?: boolean;

  /** When true, the textarea's value cannot be edited by the user. */
  readOnly?: boolean;

  /**
   * Number of visible text lines. Only meaningful when `fieldSizing` is
   * `"fixed"` — browsers ignore `rows`/`cols` once `field-sizing: content`
   * is active. Default: `4`.
   */
  rows?: number;

  /** Number of visible character columns. See `rows` for caveats. */
  cols?: number;

  /** See `PiTextAreaFieldSizing`. Default: `"fixed"`. */
  fieldSizing?: PiTextAreaFieldSizing;

  /**
   * CSS `resize` behaviour — whether/how the user can drag-resize the box.
   * Default: `"vertical"` when `fieldSizing` is `"fixed"`, `"none"` when
   * `fieldSizing` is `"content"` (dragging would otherwise permanently
   * defeat the content-based sizing by writing an inline width/height).
   */
  resize?: PiTextAreaResize;

  /** Minimum height. Accepts CSS units like `"2lh"`, `"4rem"`, or a number of px. */
  minHeight?: CssLength;

  /** Maximum height. Once reached, content scrolls instead of growing further. */
  maxHeight?: CssLength;

  /** Explicit width. Freezes the inline axis even when `fieldSizing="content"`. */
  width?: CssLength;

  /** Explicit height. Freezes the block axis even when `fieldSizing="content"`. */
  height?: CssLength;

  /**
   * Maximum width — a guard against an unconstrained `fieldSizing="content"`
   * box escaping its parent container.
   */
  maxWidth?: CssLength;

  /** Text direction. Default: inherited from the document. */
  dir?: "ltr" | "rtl";

  /**
   * CSS `writing-mode`. With `"vertical-rl"` the sizing axes swap: content
   * growth under `fieldSizing="content"` runs horizontally, not vertically.
   */
  writingMode?: "horizontal-tb" | "vertical-rl" | "vertical-lr";

  /**
   * When true, pressing Enter (without Shift/Ctrl/Meta/Alt) fires
   * `onSubmitted` with the current text instead of inserting a newline.
   * Shift+Enter (etc.) still inserts a newline. Default: `false`.
   */
  submitOnEnter?: boolean;

  /** Additional class names merged onto the root `<textarea>`. */
  className?: string;

  /** Additional inline styles merged onto the root `<textarea>` (highest precedence). */
  style?: CSSProperties;
};

export type PiTextAreaChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New value after the change. */
  value: string;
};

export type PiTextAreaSubmittedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** The current text at the time Enter was pressed. */
  value: string;
};

export type PiTextAreaEvents = {
  onChanged: PiTextAreaChangedEvent;
  onSubmitted: PiTextAreaSubmittedEvent;
};
